import logging
import os.path
import itertools
from .exception import BTSSMExecutionError, CLIToolsMissing


class CommandBuilder(object):

    def _create_flags_string(self, flags):
        return '' if flags is None else '-{}'.format(' -'.join(flags))

    def _create_params_string(self, params, sort_params=True):
        if params is None:
            return ''
        params_string = ''
        for key, value in sorted(params.items()) if sort_params else params.items():
            if value is not None:
                params_string += '-{} {} '.format(key, value)
        return params_string


class CommandLineToolCommandBuilder(CommandBuilder):
    """A class for building the shell command needed to execute BTSCommandLineTool."""

    def __init__(self, host_ip, executor, jars_path=None):
        """
        :param string   host_ip:   IP Address of remote/local host.
        :param Executor executor:  Current session executor instance.
        :param string   jars_path: System path to the jars folder provided by BTSCommandLineTools.
        """
        self._log = logging.getLogger(__name__)
        self._validate_jars_path(jars_path, host_ip, executor)
        self._java_path = self._select_java_path(jars_path, executor)
        self._jars_path = jars_path
        self._jar_files = self._get_jar_file_list(host_ip, executor)

    def build(self, op, params=None, flags=None):
        """Build a command based on the provided parameters.

        :param string     op:     Operation parameter, e.g. swupdate.
        :param dictionary params: List of parameters for the specified operation,
                                  e.g. pw=Nemuadmin:nemuuser will be params={'pw': 'Nemuadmin:nemuuser'}
        :param list       flags:  Some flags needed to execute specified command properly e.g. -activate will be ['activate']

        :return: Built shell command ready to execute.
        :rtype: string
        """

        cmd = self._build_base_cmd(op)
        if 'stopupdate' != op:
            cmd += self._create_operation_string(op)
            cmd += self._create_params_string(params)
            cmd += self._create_flags_string(flags)
        cmd = cmd.strip()
        self._log.debug(cmd)
        return cmd

    def _build_base_cmd(self, op):
        """Build base command based on folder content.

        :note: All jar files available in jars_path folder will become a part of created command.
        """
        absolute_jar_file_paths = ['{pathsep}"{path}{sep}{filename}"'.format(filename=item, pathsep=os.pathsep, path=self._jars_path, sep=os.path.sep)
                                   for item in self._jar_files]
        cmd = '{} -Djava.awt.headless=true -Xmx512m -XX:MaxPermSize=128m -classpath .'.format(self._java_path) + ''.join(absolute_jar_file_paths)
        swabortclient = ' com.nokia.em.bts.coreasset.application.util.SwAbortClient '
        coretoolapp = ' com.nokia.em.bts.coreasset.application.CoreAssetToolApplication '
        cmd += swabortclient if op == 'stopupdate' else coretoolapp
        return cmd

    def _create_operation_string(self, operation):
        return '-op {} '.format(operation)

    def _get_jar_file_list(self, host_ip, executor):
        if host_ip in ('localhost', '127.0.0.1'):
            files = os.listdir(self._jars_path)
        else:
            files = executor.run('ls "{}"'.format(self._jars_path)).split()
        return filter(lambda item: item.endswith(".jar"), files)

    def _select_java_path(self, jars_path, executor):
        """ Implemented to address compatibility issues on FSME."""
        java_path = "{}/../jre/bin/java".format(jars_path)
        try:
            executor.run('ls "{}"'.format(java_path))
            return java_path
        except BTSSMExecutionError as e:
            self._log.warning("BTS SEM CLI Tools' built-in java does not exist in '{}'! Using system 'java'.".format(java_path))
            return "java"

    def _validate_jars_path(self, jars_path, host_ip, executor):
        try:
            if host_ip in ('localhost', '127.0.0.1'):
                if not os.path.isdir(jars_path):
                    raise OSError
            else:
                executor.run('ls "{}"'.format(jars_path))
        except (OSError, BTSSMExecutionError) as e:
            raise CLIToolsMissing("BTS SEM CLI Tools not installed in '{}'.\n"
                                  "Please install CLI Tools first before using the library.\n"
                                  "To install UTE-compatible CLI Tools, run the command 'apt-get install ute-btssm-cli'.\n"
                                  "For standalone testlines, please see "
                                  "http://doc.ute.inside.nsn.com/packages/ute_btssm/interfaces/ute_btssm.html#installation".format(jars_path))


class TRSCommandBuilder(CommandBuilder):
    """A class that constructs the UNIX shell string to execute BTSSM TRS command."""

    def __init__(self, host_ip, executor, jars_path=None):
        self._java_path = 'java'
        self._jars_path = jars_path

    def build(self, op=None, params=None, zip_params=None):
        """
        TRS command to add certificate on BTSSM.
        :param params:  List of required inputs to execute the add certificate JAVA command.
        :return:
        """

        jar_files = ["trsmanager.jar", "poseidon.jar", "rpmaster.jar", "sitemgr.jar", "laf.jar", "log4j.jar"]
        cmd_template = 'sudo {java_path} -classpath .'
        os_sep = ':' if os.name is 'posix' else ';'
        for jar_file in jar_files:
            cmd_template += os_sep + '{path}{sep}' + jar_file
        cmd_template += ' -Djava.awt.headless=true' \
                        ' -Duser.country=US' \
                        ' -Duser.language=en com.nokia.em.sitemgr.SitemgrStarter' \
                        ' -conffile TrsSiteManager_noclTrs_cmdline.xml' \
                        ' -log:debug -cltMode -standalonetrs on -trsIgnoreVersionCheck' \
                        ' -clurl file:{path}{sep}..{sep}cl_cmd.xml' \
                        ' {ne} '
        cmd_template = cmd_template.format(java_path=self._java_path, ne=params['ne'], path=self._jars_path, sep=os.path.sep)

        operation_string = '-{} '.format(op) if op is not None else ''
        credentials_string = self._create_credentials_string(params)
        params_string = self._create_params_string(params, False)

        cmd_template += credentials_string
        cmd_template += operation_string
        cmd_template += params_string

        cmd_template += self._create_zip_string(zip_params)
        return cmd_template.strip()

    def _create_zip_string(self, zip_params):
        if zip_params is None:
            return ''
        options = zip_params.pop()
        zipped = ''
        for value in range(len(zip_params)):
            for key in range(len(options)):
                zipped += '-{} {} '.format(options[key], zip_params[value][key])
        return zipped

    def _create_credentials_string(self, params):
        result = ''
        if 'ne' in params:
            result += '-ne {} '.format(params.pop('ne'))
        if 'pw' in params:
            result += '-pw {} '.format(params.pop('pw'))
        return result


class BTSSMCommandBuilder(CommandBuilder):
    """A class for building the shell command needed to execute BTSSM."""

    def __init__(self, install_location):
        """
        :param string install_location: Path where BTS SM is installed.
        """
        self._log = logging.getLogger(__name__)
        self.install_location = install_location

    def build(self, java_path, params=None, flags=None):
        """Build a command based on the provided parameters.

        :param string     op:     Operation parameter, e.g. swupdate.
        :param dictionary params: List of parameters for the specified operation,
                                  e.g. pw=Nemuadmin:nemuuser will be params={'pw': 'Nemuadmin:nemuuser'}
        :param list       flags:  Some flags needed to execute specified command properly e.g. -activate will be ['activate']

        :return: Built shell command ready to execute.
        :rtype: string
        """

        cmd = self._build_base_cmd(java_path)
        cmd += self._create_params_string(params)
        cmd += self._create_flags_string(flags)
        cmd = cmd.strip()
        self._log.debug(cmd)
        return cmd

    def _build_base_cmd(self, java_path):
        """Build base command based on folder content.

        :note: All jar files available in jars_path folder will become a part of created command.
        """
        cmd = ('cd "{install_location}";'
               'sudo {java_path} -Djava.awt.headless=true -classpath ./cl/cl.jar -client com.nokia.em.poseidon.PoseidonStarter '
               '-confFile ./cl/CLConf.xml ')
        return cmd.format(java_path=java_path, install_location=self.install_location)


class CollectFilesPathBuilder(object):

    CMD_MAPPING = {
        "tests":        ["ActiveTests.xml"],
        "all":          ["FileDirectory.xml", "SWDLreport.txt"],
        "siteconf":     ["siteconf.xml"],
        "alarms":       ["alarms.xml"],
        "radparams":    ["RaDParamsFromRDLegacy.xml"],
        "swconfig":     ["swconfig.txt"],
        "currentbd":    ["currentBD.xml"],
        "rawalarms":    ["RawAlarmHistory.txt"],
        "comm":         ["scf.xml"],
        "trs":          ["ExtendedNeLogs.tar.gz", "TRS.xml", "TRS_PM.xml"],
        "fullcoverage": ['BTSLogFiles.zip'],
        "techlogs":     ['BTSLogFiles.zip'],
        "pm":           ["PMFiles.zip"],
        "trsscf":       ["TRS.xml"],
        "freqhistory":  ["FrequencyHistory.xml"]
    }

    def __new__(cls, option, exec_path, trs_ip, executor, filepath=None, filenames=None, symlink=None, *args, **kwargs):
        """Returns path to file based on execution path and TRS IP address of FSM.

        :param string option: Type of BTSCommandLineTools collect file action.
        :param string exec_path: Path to directory where BTSCommandLineTools where executed.
        :param string trs_ip: FSM TRS IP address.
        :param string filepath: Path to file that was specified for BTSCommandLineTools.
        :param string symlink: Symlink to specified directory/file. If None, no symlink will be created.

        :return: List of files that will be/was downloaded by BTSCommandLineTools.
        :rtype: list
        """
        tool_logs = [os.path.join(exec_path, "ToolLog.xml"), os.path.join(exec_path, "Tool.log"), os.path.join(exec_path, "PoseidonLog.xml")]
        conf = [os.path.join(exec_path, "conf")]
        licencefile = []

        if filepath:
            filenames = [os.path.basename(filepath)]

        elif option == 'all':
            filenames = list(itertools.chain(*[value for key, value in cls.CMD_MAPPING.items()]))

        elif option in cls.CMD_MAPPING:
            filenames = cls.CMD_MAPPING[option]

        elif option == 'querylicence':
            licencefile = [os.path.join(exec_path,
                                        executor.run_ignoring_rc('ls -t "{}"/ | egrep "_licences_.*\.xml$" | head -1'.format(exec_path)).strip())]

        filespath = [os.path.join(exec_path, "{}_{}".format(trs_ip, each))for each in filenames] if filenames is not None else []
        summary_file = [os.path.join(exec_path,
                                     executor.run_ignoring_rc('ls -t "{}"/ | egrep "_Summary_.*\.txt$" | head -1'.format(exec_path)).strip())]

        files = filespath + tool_logs + summary_file

        if licencefile:
            files += licencefile

        if symlink:
            return files + conf

        return files
